package ru.kstolu.app;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import java.io.*;import java.time.Duration;import java.util.concurrent.atomic.AtomicInteger;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,qualifiers="w390dp-h844dp-mdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class NewFeaturesTest {
 private org.robolectric.android.controller.ActivityController<MainActivity> controller;private MainActivity host;
 @Before public void setup(){ApiClient.configureForTests(url->{throw new AssertionError("No paid requests: "+url);});controller=Robolectric.buildActivity(MainActivity.class).setup();host=controller.get();}
 @After public void close(){TimerAlarm.cancel(host);controller.pause().stop().destroy();ApiClient.restoreTransport();}
 private JSONObject item()throws Exception{return new JSONObject("{\"portions\":4,\"currency\":\"RUB\",\"recipe\":{\"status\":\"ok\",\"title\":\"Паста с томатами\",\"description\":\"Быстрый соус\",\"servings\":2,\"prep_minutes\":5,\"cook_minutes\":10,\"ingredients\":[{\"name\":\"Масло\",\"amount\":10,\"unit\":\"ml\",\"price\":null},{\"name\":\"Томаты\",\"amount\":200,\"unit\":\"g\",\"price\":null}],\"steps\":[{\"title\":\"Соус\",\"body\":\"Прогрейте томаты на среднем огне\",\"ingredient_indexes\":[0,1],\"timer_seconds\":180}],\"warnings\":[]}}");}
 private TextView find(View v,String s){if(v instanceof TextView&&((TextView)v).getText().toString().equals(s))return (TextView)v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){TextView t=find(g.getChildAt(i),s);if(t!=null)return t;}}return null;}
 private void draw(View v,String name)throws Exception{v.measure(View.MeasureSpec.makeMeasureSpec(390,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(720,View.MeasureSpec.EXACTLY));v.layout(0,0,390,720);Bitmap b=Bitmap.createBitmap(390,720,Bitmap.Config.ARGB_8888);v.draw(new Canvas(b));File f=new File("build/visual-qa-1.1");f.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(f,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
 @Test public void ingredientsScaleAndOldRecipeHasNoGuesses()throws Exception{JSONObject r=item().getJSONObject("recipe");assertEquals("Масло — 20 мл\nТоматы — 400 г",StepIngredients.label(r,0,4));r.getJSONArray("steps").getJSONObject(0).remove("ingredient_indexes");assertEquals("",StepIngredients.label(r,0,4));}
 @Test public void exactBackgroundAlarmReceiverOnceAndCancellation()throws Exception{
  Shadows.shadowOf(host.getApplication()).grantPermissions("android.permission.POST_NOTIFICATIONS");org.robolectric.shadows.ShadowAlarmManager.setCanScheduleExactAlarms(true);assertTrue(TimerAlarm.schedule(host,"test-key",SystemClock.elapsedRealtime()+180000,"Соус",item().toString()));
  AlarmManager alarms=host.getSystemService(AlarmManager.class);assertNotNull(Shadows.shadowOf(alarms).peekNextScheduledAlarm());String token=host.getSharedPreferences(TimerAlarm.PREF,0).getString("token",null);
  Intent i=new Intent(host,TimerAlarmReceiver.class).setAction("ru.kstolu.TIMER").putExtra("token",token);host.sendBroadcast(i);Shadows.shadowOf(Looper.getMainLooper()).idle();assertFalse(TimerAlarm.foreground(host,"test-key"));assertNotNull(Shadows.shadowOf(host.getSystemService(NotificationManager.class)).getNotification(TimerAlarm.ID));host.sendBroadcast(i);Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofSeconds(4));assertFalse(TimerAlarm.consume(host,token));
  assertTrue(TimerAlarm.schedule(host,"test-key",SystemClock.elapsedRealtime()+180000,"Соус",item().toString()));token=host.getSharedPreferences(TimerAlarm.PREF,0).getString("token",null);TimerAlarm.cancelFor(host,"test-key");assertFalse(TimerAlarm.consume(host,token));assertNull(Shadows.shadowOf(alarms).peekNextScheduledAlarm());
 }
 @Test public void deniedExactPermissionDoesNotPretendBackgroundWorks()throws Exception{org.robolectric.shadows.ShadowAlarmManager.setCanScheduleExactAlarms(false);assertFalse(TimerAlarm.schedule(host,"k",SystemClock.elapsedRealtime()+1000,"Соус",item().toString()));}
 @Test public void populatedSheetAndStepAreReadable()throws Exception{JSONObject snapshot=item();String key=Library.id(snapshot.getJSONObject("recipe"));host.getSharedPreferences("sous-chef",0).edit().putBoolean("consent",true).putString(key,"[{\"role\":\"user\",\"content\":\"На каком огне?\"},{\"role\":\"assistant\",\"content\":\"На среднем. Если томаты быстро темнеют, уменьшите нагрев.\"}]").commit();new SousChefSheet(host,snapshot,()->0,()->75).show();Dialog d=org.robolectric.shadows.ShadowDialog.getLatestDialog();draw(d.getWindow().getDecorView(),"sous-chef-answer");d.dismiss();InlineCooking c=new InlineCooking(host,snapshot);draw(c,"step-ingredients");c.suspendTimer();}
 @Test public void sheetHasRecipeContextAndOpeningDoesNotCallModel()throws Exception{
  AtomicInteger calls=new AtomicInteger();ApiClient.configureForTests(url->{calls.incrementAndGet();throw new AssertionError("Opening must be free");});new SousChefSheet(host,item(),()->0,()->42).show();Dialog d=org.robolectric.shadows.ShadowDialog.getLatestDialog();assertNotNull(find(d.getWindow().getDecorView(),"Су-шеф"));draw(d.getWindow().getDecorView(),"sous-chef-empty");assertEquals(0,calls.get());d.dismiss();
 }
}
